  1: // =====================================================
  2: // WebDavClient.ets - Minimal WebDAV client via @ohos.net.http
  3: // Supports PUT/GET/HEAD/DELETE with Basic Auth.
  4: // =====================================================
  5: 
  6: import http from '@ohos.net.http';
  7: import { Base64Util } from './Base64Util';
  8: import { WebDavLogger } from '../../utils/WebDavLogger';
  9: import type { IWebDavBackend } from './IWebDavBackend';
 10: 
 11: export interface WebDavResponse {
 12:   statusCode: number;
 13:   headers: Record<string, string>;
 14:   body: string;
 15: }
 16: 
 17: interface HttpErrorInfo {
 18:   code: string;
 19:   message: string;
 20: }
 21: 
 22: export class WebDavClient implements IWebDavBackend {
 23:   private endpoint: string;
 24:   private authHeader: string;
 25:   private static readonly MAX_REDIRECTS: number = 2;
 26: 
 27:   constructor(endpoint: string, username: string, password: string) {
 28:     this.endpoint = endpoint.replace(/\/+$/g, '');
 29:     const raw = `${username}:${password}`;
 30:     this.authHeader = `Basic ${Base64Util.encodeUtf8String(raw)}`;
 31:   }
 32: 
 33:   async get(path: string): Promise<WebDavResponse> {
 34:     return this.request(http.RequestMethod.GET, path, {}, undefined);
 35:   }
 36: 
 37:   async head(path: string): Promise<WebDavResponse> {
 38:     return this.request(http.RequestMethod.HEAD, path, {}, undefined);
 39:   }
 40: 
 41:   async put(path: string, body: string, contentType: string = 'application/octet-stream', extraHeaders: Record<string, string> = {}, ensureDir: boolean = true): Promise<WebDavResponse> {
 42:     const headers: Record<string, string> = { 'Content-Type': contentType };
 43:     Object.keys(extraHeaders).forEach((key: string) => {
 44:       headers[key] = extraHeaders[key];
 45:     });
 46: 
 47:     // 自动创建父目录
 48:     if (ensureDir) {
 49:       await this.ensureParentExists(path);
 50:     }
 51: 
 52:     return this.request(http.RequestMethod.PUT, path, headers, body);
 53:   }
 54: 
 55:   private async ensureParentExists(path: string): Promise<void> {
 56:     const lastSlash = path.lastIndexOf('/');
 57:     if (lastSlash <= 0) return;
 58: 
 59:     const parent = path.substring(0, lastSlash);
 60:     if (parent.length === 0 || parent === '/') return;
 61: 
 62:     try {
 63:       const headRes = await this.head(parent);
 64:       if (headRes.statusCode === 404) {
 65:         // 递归创建父目录
 66:         await this.ensureParentExists(parent);
 67:         await this.mkcol(parent);
 68:       }
 69:     } catch (e) {
