 95:   private normalizeHeaders(headers: Record<string, string | string[] | number | undefined>): Record<string, string> {
 96:     const out: Record<string, string> = {};
 97:     for (const k of Object.keys(headers)) {
 98:       const v = headers[k];
 99:       if (v === undefined) continue;
100:       if (Array.isArray(v)) {
101:         out[k.toLowerCase()] = v.join(',');
102:       } else {
103:         out[k.toLowerCase()] = String(v);
104:       }
105:     }
106:     return out;
107:   }
