109:   private async request(method: http.RequestMethod, path: string, headers: Record<string, string>, body?: string): Promise<WebDavResponse> {
110:     const requestId = this.newRequestId();
111:     return this.requestWithRedirect(method, path, headers, body, WebDavClient.MAX_REDIRECTS, requestId);
112:   }
113: 
114:   private async requestWithRedirect(
115:     method: http.RequestMethod,
116:     path: string,
117:     headers: Record<string, string>,
118:     body: string | undefined,
119:     redirectsLeft: number,
120:     requestId: string
121:   ): Promise<WebDavResponse> {
122:     const startMs = Date.now();
123:     const request = http.createHttp();
124: 
125:     const url = this.buildUrl(path);
126:     // Merge headers manually to avoid spread operator issues
127:     const allHeaders: Record<string, string> = {
128:       'Authorization': this.authHeader,
129:       'Accept': '*/*'
130:     };
131:     // Add custom headers
132:     Object.keys(headers).forEach((key: string) => {
133:       allHeaders[key] = headers[key];
134:     });
135: 
136:     try {
137:       const options: http.HttpRequestOptions = {
138:         method,
139:         header: allHeaders,
140:         connectTimeout: 15000,
141:         readTimeout: 20000
142:       };
143:       if (body !== undefined && (method === http.RequestMethod.PUT || method === http.RequestMethod.POST)) {
144:         options.extraData = body;
145:       }
146:       const res = await request.request(url, options);
147: 
148:       const statusCode = res.responseCode ?? 0;
149:       // Ensure res.header is treated as the correct type
150:       const resHeaders = this.normalizeHeaders(res.header as Record<string, string | string[] | number | undefined>);
151:       const raw = res.result;
152:       let bodyStr = '';
153:       if (typeof raw === 'string') {
154:         bodyStr = raw;
155:       } else if (raw instanceof ArrayBuffer) {
156:         // Decode as UTF-8-ish text (best-effort)
157:         const bytes = new Uint8Array(raw);
158:         bodyStr = '';
159:         for (const b of bytes) bodyStr += String.fromCharCode(b);
160:       } else {
161:         bodyStr = '';
162:       }
163: 
164:       request.destroy();
165:       const elapsed = Date.now() - startMs;
166:       if (redirectsLeft > 0 && (statusCode === 301 || statusCode === 302 || statusCode === 303 || statusCode === 307 || statusCode === 308)) {
167:         const location = resHeaders['location'] ?? '';
168:         WebDavLogger.infoRequest(requestId, String(method), url, statusCode, location, elapsed);
169:         if (location.length > 0) {
170:           return this.requestWithRedirect(method, location, headers, body, redirectsLeft - 1, requestId);
171:         }
172:       }
173:       WebDavLogger.infoRequest(requestId, String(method), url, statusCode, '', elapsed);
174:       return { statusCode, headers: resHeaders, body: bodyStr };
175:     } catch (e) {
176:       request.destroy();
177:       const err = this.buildHttpErrorInfo(e as (object | string | number | boolean | null | undefined));
178:       const elapsed = Date.now() - startMs;
179:       WebDavLogger.errorRequest(requestId, String(method), url, err.code, err.message, elapsed);
180:       return { statusCode: 0, headers: {}, body: err.message };
181:     }
182:   }
183: 
184:   private buildHttpErrorInfo(e: object | string | number | boolean | null | undefined): HttpErrorInfo {
185:     if (e === null || e === undefined) {
186:       return { code: '', message: 'unknown_error' };
187:     }
188:     if (typeof e === 'string' || typeof e === 'number' || typeof e === 'boolean') {
189:       return { code: '', message: String(e) };
190:     }
191:     if (e instanceof Error) {
192:       const name = e.name ?? '';
193:       const msg = e.message ?? '';
194:       if (name.length > 0 && msg.length > 0) {
195:         return { code: '', message: `${name}: ${msg}` };
196:       }
197:       if (msg.length > 0) {
198:         return { code: '', message: msg };
199:       }
200:       return { code: '', message: name.length > 0 ? name : 'error' };
201:     }
202: 
203:     const obj = e as Record<string, string | number | boolean | object | undefined | null>;
204:     const codeVal = obj['code'];
205:     const messageVal = obj['message'];
206:     const nameVal = obj['name'];
207: 
208:     const code = (typeof codeVal === 'string' || typeof codeVal === 'number') ? String(codeVal) : '';
209:     const message = typeof messageVal === 'string' ? messageVal : '';
210:     const name = typeof nameVal === 'string' ? nameVal : '';
211:     const raw = this.safeJsonStringify(obj);
212: 
213:     if (code.length > 0 || message.length > 0) {
214:       const title = name.length > 0 ? name : 'BusinessError';
215:       const core = `${title}: ${message.length > 0 ? message : 'unknown'}`;
216:       if (raw.length > 0) {
217:         return { code, message: `${core} raw=${raw}` };
218:       }
219:       return { code, message: core };
220:     }
221:     if (raw.length > 0) {
222:       return { code: '', message: raw };
223:     }
224:     return { code: '', message: 'unknown_error_object' };
225:   }
226: 
227:   private safeJsonStringify(obj: Record<string, string | number | boolean | object | undefined | null>): string {
228:     try {
229:       const s = JSON.stringify(obj);
230:       if (typeof s === 'string') {
231:         return s;
232:       }
233:       return '';
234:     } catch (e) {
235:       return '';
236:     }
237:   }
238: 
239:   private newRequestId(): string {
240:     const rand = Math.random().toString(36).substring(2, 8);
241:     return `${Date.now()}_${rand}`;
242:   }
