280:   private async preflightRemoteRoot(client: IWebDavBackend): Promise<WebDavSyncResult | null> {
281:     const key = `${safeTrim(this.settings.endpoint)}|${safeTrim(this.settings.remoteRoot)}`;
282:     if (this.remoteLayoutKey === key) {
283:       return null;
284:     }
285: 
286:     const remoteRoot = normalizeRoot(this.settings.remoteRoot);
287:     if (remoteRoot === '/') {
288:       this.remoteLayoutKey = key;
289:       this.remoteLayoutBase = '/';
290:       this.remoteLayoutPrefix = '';
291:       return null;
292:     }
293: 
294:     const rootHead = await client.head(remoteRoot);
295:     if (this.isCollectionReachable(rootHead.statusCode)) {
296:       this.remoteLayoutKey = key;
297:       this.remoteLayoutBase = remoteRoot;
298:       this.remoteLayoutPrefix = '';
299:       return null;
300:     }
301: 
302:     // 目录不存在，尝试创建
303:     if (rootHead.statusCode === 404) {
304:       console.info(`[WebDavSyncManager] Remote directory ${remoteRoot} not found, trying to create it`);
305:       const createResult = await this.ensureRemoteDirectory(client, remoteRoot);
306:       if (createResult !== null) {
307:         return createResult;
308:       }
309:       // 创建成功，重新检查
310:       const recheckHead = await client.head(remoteRoot);
311:       if (this.isCollectionReachable(recheckHead.statusCode)) {
312:         this.remoteLayoutKey = key;
313:         this.remoteLayoutBase = remoteRoot;
314:         this.remoteLayoutPrefix = '';
315:         return null;
316:       }
317:     }
318: 
319:     const probeRemoteRoot = await this.probeCollectionWritable(client, remoteRoot);
320:     if (probeRemoteRoot === null) {
321:       this.remoteLayoutKey = key;
322:       this.remoteLayoutBase = remoteRoot;
323:       this.remoteLayoutPrefix = '';
324:       return null;
325:     }
326: 
327:     if (this.settings.requireRemoteRootExists) {
328:       return probeRemoteRoot;
329:     }
330: 
331:     const prefix = `${this.sanitizePrefix(remoteRoot)}__`;
332:     const probe = await this.probeRootWritable(client, prefix);
333:     if (probe !== null) {
334:       return probe;
335:     }
336:     this.remoteLayoutKey = key;
337:     this.remoteLayoutBase = '/';
338:     this.remoteLayoutPrefix = prefix;
339:     return null;
340:   }
