 17:   async backupToCloud(
 18:     client: IWebDavBackend,
 19:     settings: WebDavSettings,
 20:     manifest: WebDavManifest,
 21:     remoteFile: string
 22:   ): Promise<WebDavSyncResult> {
 23:     const exportStartMs = Date.now();
 24:     const exportResult = await this.syncManager.exportData();
 25:     const exportElapsedMs = Date.now() - exportStartMs;
 26:     console.info(`[WebDAV] backup export ms=${exportElapsedMs}`);
 27:     if (!exportResult.success) {
 28:       return WebDavSyncResult.fail('导出失败', exportResult.error);
 29:     }
 30: 
 31:     await new Promise<void>((resolve) => setTimeout(resolve, 50));
 32: 
 33:     const dataSize = exportResult.data.length;
 34:     console.info(`[WebDAV] backup data size=${dataSize}`);
 35:     
 36:     if (dataSize > 5 * 1024 * 1024) {
 37:       console.warn(`[WebDAV] backup data too large: ${dataSize} bytes`);
 38:     }
 39: 
 40:     await new Promise<void>((resolve) => setTimeout(resolve, 0));
 41: 
 42:     const encStartMs = Date.now();
 43:     const enc = await WebDavCrypto.encryptUtf8Offloaded(exportResult.data, settings.syncPassword);
 44:     const encElapsedMs = Date.now() - encStartMs;
 45:     console.info(`[WebDAV] backup encrypt ms=${encElapsedMs}`);
 46:     
 47:     await new Promise<void>((resolve) => setTimeout(resolve, 50));
 48:     
 49:     const putStartMs = Date.now();
 50:     const putRes = await client.put(remoteFile, enc, 'application/json');
 51:     const putElapsedMs = Date.now() - putStartMs;
 52:     console.info(`[WebDAV] backup put status=${putRes.statusCode} ms=${putElapsedMs}`);
 53:     
 54:     if (putRes.statusCode < 200 || putRes.statusCode >= 300) {
 55:       return WebDavSyncResult.fail('上传失败', `PUT ${putRes.statusCode}: ${putRes.body}`);
 56:     }
 57: 
 58:     await new Promise<void>((resolve) => setTimeout(resolve, 0));
 59: 
 60:     const headRes = await client.head(remoteFile);
 61:     manifest.lastBackupUploadMs = Date.now();
 62:     manifest.lastBackupEtag = safeTrim(headRes.headers['etag'] ?? '');
 63:     await this.store.saveManifestJson(manifest.toJSON());
 64: 
 65:     return WebDavSyncResult.ok('备份已上传');
 66:   }
