 68:   async downloadBackupPlain(
 69:     client: IWebDavBackend,
 70:     settings: WebDavSettings,
 71:     manifest: WebDavManifest,
 72:     remoteFile: string,
 73:     legacyRemoteFile: string,
 74:     force: boolean
 75:   ): Promise<WebDavBackupPlainResult> {
 76:     let targetFile = remoteFile;
 77:     
 78:     if (!force) {
 79:       let headRes = await client.head(targetFile);
 80:       if (headRes.statusCode === 404) {
 81:         const legacyHead = await client.head(legacyRemoteFile);
 82:         if (legacyHead.statusCode !== 404) {
 83:           targetFile = legacyRemoteFile;
 84:           headRes = legacyHead;
 85:         }
 86:       }
 87:       
 88:       const conflict = WebDavConflictResolver.checkBackupRestore(headRes, manifest, force);
 89:       if (conflict) {
 90:         // Special handling for "IDLE" status result from resolver which means we should stop but it's not an error
 91:         // But here we need to return WebDavBackupPlainResult
 92:         return new WebDavBackupPlainResult(conflict, '');
 93:       }
 94:     }
 95: 
 96:     const snapshot = await this.syncManager.exportData();
 97:     if (snapshot.success) {
 98:       await this.store.saveSnapshotJson(snapshot.data);
 99:     }
100: 
101:     const getRes = await client.get(targetFile);
102:     if (getRes.statusCode < 200 || getRes.statusCode >= 300) {
103:       return new WebDavBackupPlainResult(
104:         WebDavSyncResult.fail('下载失败', `GET ${getRes.statusCode}: ${getRes.body}`),
105:         ''
106:       );
107:     }
108: 
109:     let plain: string;
110:     try {
111:       plain = await WebDavCrypto.decryptUtf8Offloaded(getRes.body, settings.syncPassword);
112:     } catch (ce) {
113:       const msg = ce instanceof CryptoError ? ce.message : String(ce);
114:       return new WebDavBackupPlainResult(WebDavSyncResult.fail('解密失败', msg), '');
115:     }
116: 
117:     return new WebDavBackupPlainResult(WebDavSyncResult.ok('已下载云端备份'), plain);
118:   }
