155:       return WebDavSyncResult.fail('下载失败', `GET ${getRes.statusCode}: ${getRes.body}`);
156:     }
157: 
158:     let plain: string;
159:     try {
160:       plain = await WebDavCrypto.decryptUtf8Offloaded(getRes.body, settings.syncPassword);
161:     } catch (ce) {
